SELECT
    ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('order_date')} AS time,
    COUNT(1) AS currentMonthCount
FROM crm_contract
WHERE deleted = 0
AND audit_status = ${@cn.iocoder.yudao.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
AND owner_user_id in

        #{userId}

AND order_date between #{times[0],javaType=java.time.LocalDateTime} and
    #{times[1],javaType=java.time.LocalDateTime}
GROUP BY ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('order_date')}

SELECT
    ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('order_date')} AS time,
    COALESCE(SUM(total_price), 0) AS currentMonthCount
FROM crm_contract
WHERE deleted = 0
AND audit_status = ${@cn.iocoder.yudao.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
AND owner_user_id in

        #{userId}

AND order_date between #{times[0],javaType=java.time.LocalDateTime} and
    #{times[1],javaType=java.time.LocalDateTime}
GROUP BY ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('order_date')}

SELECT
    ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('return_time')} AS time,
    COALESCE(SUM(price), 0) AS currentMonthCount
FROM crm_receivable
WHERE deleted = 0
AND audit_status = ${@cn.iocoder.yudao.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
AND owner_user_id in

        #{userId}

AND return_time between #{times[0],javaType=java.time.LocalDateTime} and
    #{times[1],javaType=java.time.LocalDateTime}
GROUP BY ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('return_time')}

SELECT ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('contract.order_date')} AS time, COUNT(DISTINCT contract.id) AS contract_count, COALESCE(SUM(contract.total_price), 0) AS contract_price, COALESCE(SUM(receivable.receivable_price), 0) AS receivable_price, COALESCE(SUM(contract.total_price), 0) - COALESCE(SUM(receivable.receivable_price), 0) AS unreceived_price FROM crm_contract contract LEFT JOIN ( SELECT contract_id, COALESCE(SUM(price), 0) AS receivable_price FROM crm_receivable WHERE deleted = 0 AND audit_status = ${@cn.iocoder.yudao.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status} GROUP BY contract_id ) receivable ON contract.id = receivable.contract_id WHERE contract.deleted = 0 AND contract.audit_status = ${@cn.iocoder.yudao.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status} AND contract.owner_user_id in
#{userId}
AND contract.order_date between #{times[0],javaType=java.time.LocalDateTime} and #{times[1],javaType=java.time.LocalDateTime} GROUP BY ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@formatYearMonth('contract.order_date')}
